#include <iostream>
#include <memory>
#include <utility>

struct Request {
    int id = 7;

    ~Request() {
        std::cout << "销毁请求\n";
    }
};

int main() {
    std::weak_ptr<Request> watch;

    {
        auto req = std::make_shared<Request>();
        watch = req;

        std::cout << "强引用数 " << req.use_count() << "\n";
        std::cout << "块内过期 " << watch.expired() << "\n";

        if (auto current = watch.lock()) {
            std::cout << "访问请求 " << current->id << "\n";
        }
    } // A

    std::cout << "块外过期 " << watch.expired() << "\n";

    if (auto current = watch.lock()) {
        std::cout << "访问请求 " << current->id << "\n";
    } else {
        std::cout << "请求已不存在\n";
    }
}
